--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker is a UObject held only by an untracked raw pointer. Garbage collection can reclaim it; a later goal calls AddPoints through the dangling pointer.",
  "no_colors_cause": "The palette is loaded by a string path and its directory is not included in the cook, so the packaged build cannot find DA_Primary and falls back to gray."
}


--- tmp/check_packaging.py ---
from pathlib import Path
h = Path('Source/PixelArena/ArenaGameMode.h').read_text()
c = Path('Config/DefaultGame.ini').read_text()
assert 'UPROPERTY()\n\tTObjectPtr<UArenaScoreTracker> ScoreTracker' in h, 'ScoreTracker must be GC-tracked'
assert '+DirectoriesToAlwaysCook=(Path="/Game/Data/Palettes")' in c, 'Palette directory must be cooked'
print('Packaged-build source checks passed')
